"""Restore Spanish diacritics using an inline frequency dictionary."""

import re
import unicodedata

FREQ = {
    "esta": 800, "está": 600,
    "si": 900, "sí": 700,
    "mas": 100, "más": 950,
    "el": 990, "él": 400,
    "tu": 500, "tú": 450,
    "como": 800, "cómo": 300,
    "papa": 50, "papá": 300,
    "año": 400, "ano": 5,
    "niño": 350, "nino": 0,
}


def _strip_accents(word: str) -> str:
    return "".join(
        ch for ch in unicodedata.normalize("NFD", word)
        if unicodedata.category(ch) != "Mn"
    )


def _match_case(original: str, replacement: str) -> str:
    """Capitalize the replacement if the original token was capitalized."""
    if original and original[0].isupper():
        return replacement[0].upper() + replacement[1:]
    return replacement


# Index dictionary by accent-stripped key -> best candidate.
_BEST = {}
for cand, freq in FREQ.items():
    key = _strip_accents(cand)
    if key not in _BEST or freq > FREQ[_BEST[key]]:
        _BEST[key] = cand

_TOKEN_RE = re.compile(r"([A-Za-zÁÉÍÓÚÑáéíóúñü]+)")


def restore_token(token: str) -> str:
    m = _TOKEN_RE.fullmatch(token)
    if not m:
        return token
    word = token
    best = _BEST.get(_strip_accents(word.lower()))
    if best is None:
        return token
    return _match_case(word, best)


def restore_token_with_punct(token: str) -> str:
    """Restore a token that may carry attached punctuation."""
    m = _TOKEN_RE.search(token)
    if not m:
        return token
    start, end = m.span()
    core = restore_token(m.group(0))
    return token[:start] + core + token[end:]


def restore_text(text: str) -> str:
    return "".join(
        restore_token_with_punct(tok)
        for tok in re.split(r"([A-Za-zÁÉÍÓÚÑáéíóúñü]+(?:[,.;:!?]*)?)", text)
        if tok
    )

